<script setup lang="ts">
import { computed, ref } from 'vue'

type FinanceStatus = 'processed' | 'paid' | 'pending'
type FinanceTransaction = {
  id: string
  date: string
  description: string
  detail: string
  status: FinanceStatus
  statusLabel: string
  amount: number
  kind: 'in' | 'out'
  action: string
}

const emit = defineEmits<{ openOrders: [] }>()

const activeTab = ref('Semua Transaksi')
const searchQuery = ref('')
const period = ref('30 Hari Terakhir (Juni 2024)')
const paymentMethod = ref('Semua Metode (QRIS, VA, BR)')
const withdrawalDialogOpen = ref(false)
const withdrawalAmount = ref(12450000)
const withdrawalNote = ref('')
const notice = ref('')
const withdrawalComplete = ref(false)
let noticeTimer: ReturnType<typeof setTimeout> | undefined

const transactions = ref<FinanceTransaction[]>([
  { id: 'WD-2024-0608-01', date: '8 Juni 2024, 14:15 WITA', description: 'Penarikan Saldo Toko ke Bank BRI', detail: 'No. Rek: 0128-••••-50-4 (Instant Transfer)', status: 'processed', statusLabel: 'Berhasil Diproses', amount: 10000000, kind: 'out', action: 'Unduh Bukti' },
  { id: 'ORD-PP-9801', date: '3 Juni 2024, 17:00 WITA', description: '4× Kain Tenun Ikat Sumba Motif Pahikung', detail: 'Pembeli: Hendra Wijaya (Medan, Sumut)', status: 'paid', statusLabel: 'Dana Diteruskan', amount: 950400, kind: 'in', action: 'Rincian' },
  { id: 'ORD-PP-9792', date: '2 Juni 2024, 11:20 WITA', description: '2× Kain Batik Tulis Solo Silk Premium', detail: 'Pembeli: Dewi Lestari (Bandung, Jabar)', status: 'paid', statusLabel: 'Dana Diteruskan', amount: 280000, kind: 'in', action: 'Rincian' },
  { id: 'ORD-PP-9820', date: 'Hari Ini, 08:32 WITA', description: '1× Kain Batik Cap Pekalongan Megamendung', detail: 'Pembeli: Budi Santoso (Surabaya) • J&T Express', status: 'pending', statusLabel: 'Menunggu Pesanan Selesai', amount: 120000, kind: 'in', action: 'Lacak Paket' },
  { id: 'WD-2024-0525-02', date: '25 Mei 2024, 09:30 WITA', description: 'Penarikan Saldo Toko ke Bank BRI', detail: 'No. Rek: 0128-••••-50-4 (Batch Penggajian Koperasi)', status: 'processed', statusLabel: 'Berhasil Diproses', amount: 15000000, kind: 'out', action: 'Unduh Bukti' },
])

const tabs = [
  { label: 'Semua Transaksi', filter: 'all' },
  { label: 'Pemasukan Penjualan', filter: 'income' },
  { label: 'Pencairan Saldo (WD)', filter: 'withdrawal' },
  { label: 'Dana Ditahan', filter: 'held' },
]

const filteredTransactions = computed(() => {
  const query = searchQuery.value.trim().toLocaleLowerCase('id')
  const filter = tabs.find((tab) => tab.label === activeTab.value)?.filter
  return transactions.value.filter((transaction) => {
    const matchesQuery = !query || `${transaction.id} ${transaction.description} ${transaction.detail}`.toLocaleLowerCase('id').includes(query)
    const matchesTab = filter === 'all'
      || filter === 'income' && transaction.kind === 'in'
      || filter === 'withdrawal' && transaction.kind === 'out'
      || filter === 'held' && transaction.status === 'pending'
    const matchesMethod = paymentMethod.value === 'Semua Metode (QRIS, VA, BR)'
      || transaction.id.startsWith('WD-') && paymentMethod.value === 'Transfer Bank'
      || transaction.id.startsWith('ORD-') && paymentMethod.value === 'QRIS / Virtual Account'
    return matchesQuery && matchesTab && matchesMethod
  })
})

const availableBalance = computed(() => Math.max(0, 12450000 - (withdrawalComplete.value ? withdrawalAmount.value : 0)))

function notify(message: string) {
  notice.value = message
  if (noticeTimer) clearTimeout(noticeTimer)
  noticeTimer = setTimeout(() => { notice.value = '' }, 2800)
}

function formatRupiah(value: number) {
  return `Rp ${value.toLocaleString('id-ID')}`
}

function openWithdrawal() {
  withdrawalAmount.value = availableBalance.value
  withdrawalNote.value = ''
  withdrawalDialogOpen.value = true
}

function confirmWithdrawal() {
  const amount = Number(withdrawalAmount.value)
  if (!amount || amount <= 0) {
    notify('Masukkan jumlah penarikan yang valid.')
    return
  }
  if (amount > availableBalance.value) {
    notify('Jumlah melebihi saldo siap tarik.')
    return
  }
  transactions.value.unshift({
    id: `WD-2024-${String(transactions.value.length + 9).padStart(4, '0')}-01`,
    date: 'Hari Ini, baru saja',
    description: 'Penarikan Saldo Toko ke Bank BRI',
    detail: `No. Rek: 0128-••••-50-4${withdrawalNote.value ? ` • ${withdrawalNote.value}` : ''}`,
    status: 'processed',
    statusLabel: 'Berhasil Diproses',
    amount,
    kind: 'out',
    action: 'Unduh Bukti',
  })
  withdrawalComplete.value = true
  withdrawalDialogOpen.value = false
  notify(`Penarikan ${formatRupiah(amount)} berhasil diajukan ke Bank BRI.`)
}

function exportReport() {
  const rows = [['ID Transaksi', 'Tanggal', 'Deskripsi', 'Detail', 'Status', 'Nominal']]
  filteredTransactions.value.forEach((transaction) => rows.push([transaction.id, transaction.date, transaction.description, transaction.detail, transaction.statusLabel, String(transaction.amount)]))
  const csv = rows.map((row) => row.map((value) => `"${value.replace(/"/g, '""')}"`).join(',')).join('\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  const link = document.createElement('a')
  link.href = url
  link.download = 'laporan-keuangan-pasarpintar.csv'
  link.click()
  URL.revokeObjectURL(url)
  notify('Rekap akuntansi berhasil diunduh.')
}

function handleTransactionAction(transaction: FinanceTransaction) {
  if (transaction.action === 'Lacak Paket') {
    emit('openOrders')
    return
  }
  if (transaction.action === 'Unduh Bukti') {
    notify(`Bukti transfer ${transaction.id} siap diunduh.`)
    return
  }
  notify(`Rincian rekonsiliasi ${transaction.id}: ${formatRupiah(transaction.amount)}.`)
}
</script>

