    <section class="finance-balance-cards" aria-label="Ringkasan saldo toko">
      <article class="balance-card available-card"><header>Saldo Siap Tarik <span>▣</span></header><strong>{{ formatRupiah(availableBalance) }}</strong><p>Tersedia untuk ditransfer ke Bank BRI Koperasi</p><footer><small>◉ Bebas biaya admin s/d 17:00 WITA</small><button type="button" @click="openWithdrawal">Tarik Saldo</button></footer></article>
      <article class="balance-card escrow-card"><header>Dana Ditahan (Escrow) <span>♧</span></header><strong>Rp 3.820.000</strong><p>Menunggu konfirmasi penerimaan dari 19 pesanan kurir</p><footer><small class="info-note">ⓘ Dilepas otomatis 24 jam pasca paket tiba</small></footer></article>
      <article class="balance-card revenue-card"><header>Pendapatan Bersih (Juni) <span>↗ +14.2%</span></header><strong>Rp 18.450.000</strong><p>Dari 142 pesanan terkirim sukses</p><footer><small>Target bulanan koperasi <b>92.2% tercapai</b></small></footer></article>
      <article class="balance-card payout-card"><header>Pencairan Berhasil <span>✓</span></header><strong>Rp 25.000.000</strong><p>Total 3 kali pencairan ke Bank BRI Koperasi</p><footer><small>● Pencairan terakhir: Sukses (2 hari lalu)</small></footer></article>
    </section>

    <section class="finance-bank-and-subsidy"><article class="bank-account-card"><span class="bank-icon">♙</span><div><b>Bank Rakyat Indonesia (BRI)</b><strong>0128-01-002938-50-4</strong><small>a.n. Koperasi Pengrajin Tenun &amp; Batik Nusantara</small></div><span class="verified-bank">✓ Terverifikasi<br />OJK</span><button type="button" @click="notify('Form tambah atau ubah rekening bank dibuka.')">Ubah / Tambah<br />Rekening <small>Rekening Utama (Default)</small></button><span class="bank-settings">☷</span></article><article class="subsidy-card"><span>◇</span><div><b>Subsidi Biaya Layanan<br />0% <small>PROGRAM<br />KEMENKOP</small></b><p>Bebas biaya potongan transaksi platform dari Gerakan Bangga Buatan Indonesia berlaku hingga 31 Desember 2024.</p><strong>↗ Anda menghemat Rp 369.000 bulan ini</strong></div></article></section>

    <section class="finance-analysis"><article class="finance-panel cashflow-panel"><header class="finance-section-heading"><div><h2>Tren Arus Kas Mingguan</h2><p>Perbandingan Pemasukan Hasil Penjualan vs Penarikan Dana (4 Pekan)</p></div><div class="chart-legend"><span><i></i> Pemasukan Penjualan</span><span><i></i> Pencairan Dana</span></div></header><div class="cashflow-chart"><div class="cashflow-gridlines"><i></i><i></i><i></i></div><div v-for="(week, index) in [{ income: 63, payout: 0, label: 'Mgg 1 (1–7 Jun)' }, { income: 88, payout: 76, label: 'Mgg 2 (8–14 Jun)' }, { income: 71, payout: 0, label: 'Mgg 3 (15–21 Jun)' }, { income: 48, payout: 0, label: 'Mgg 4 (22–30 Jun)' }]" :key="week.label" class="cashflow-week"><div class="cashflow-bars"><i class="income-bar" :style="{ height: `${week.income}%` }"></i><i v-if="week.payout" class="payout-bar" :style="{ height: `${week.payout}%` }"></i></div><small>{{ week.label }}</small></div></div><footer class="cashflow-footer"><span>Rata-rata per transaksi: <b>Rp 130.000</b></span><span>Update rekonsiliasi otomatis setiap pukul 23:59 WITA</span></footer></article>
      <article class="finance-panel composition-panel"><header class="finance-section-heading"><div><h2>Ringkasan Komposisi Finansial</h2><p>Rincian periode berjalan</p></div><select v-model="period" aria-label="Periode ringkasan"><option>30 Hari Terakhir (Juni 2024)</option><option>7 Hari Terakhir</option><option>90 Hari Terakhir</option></select></header><dl><div><dt>Penjualan Bruto (Kotor)</dt><dd>Rp 18.720.000</dd></div><div><dt>Potongan Kupon Promo Toko</dt><dd class="negative">-Rp 270.000</dd></div><div><dt>Subsidi Biaya Kirim Pembeli</dt><dd>Rp 0 (Otomatis)</dd></div><div><dt>Biaya Admin Platform</dt><dd><span>0% Kemenkop</span> Rp 0</dd></div></dl><footer><b>Pendapatan<br />Bersih</b><strong>{{ formatRupiah(18450000) }}</strong><small>✓ Semua potongan diverifikasi akuntabel siap audit</small></footer></article></section>

    <section class="finance-ledger"><header class="ledger-heading"><div><h2>Riwayat Arus Kas &amp; Buku Kas Toko</h2><p>Daftar rekonsiliasi lengkap dari seluruh pesanan masuk, pencairan, dan<br class="finance-desktop-break" /> penahanan dana.</p></div><nav class="ledger-tabs" aria-label="Filter jenis transaksi"><button v-for="tab in tabs" :key="tab.filter" type="button" :class="{ active: activeTab === tab.label }" @click="activeTab = tab.label">{{ tab.label }}</button></nav></header><div class="ledger-filters"><label><span>⌕</span><input v-model="searchQuery" type="search" placeholder="Cari nomor transaksi, ID pesanan (#ORD), atau nama pembeli..." aria-label="Cari transaksi keuangan" /></label><select v-model="period" aria-label="Filter periode"><option>30 Hari Terakhir (Juni 2024)</option><option>7 Hari Terakhir</option><option>90 Hari Terakhir</option></select><select v-model="paymentMethod" aria-label="Filter metode pembayaran"><option>Semua Metode (QRIS, VA, BR)</option><option>QRIS / Virtual Account</option><option>Transfer Bank</option></select></div><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>ID Transaksi &amp; Waktu</th><th>Deskripsi &amp; Rincian Produk</th><th>Status Rekonsiliasi</th><th>Nominal Arus Kas</th><th>Aksi</th></tr></thead><tbody><tr v-for="transaction in filteredTransactions" :key="transaction.id"><td><div class="transaction-id"><i :class="transaction.kind">{{ transaction.kind === 'in' ? '↓' : '↗' }}</i><span><b>{{ transaction.id.startsWith('ORD-') ? `#${transaction.id}` : transaction.id }}</b><small>{{ transaction.date }}</small></span></div></td><td><b>{{ transaction.description }}</b><small>{{ transaction.detail }}</small></td><td><span class="reconciliation-status" :class="transaction.status">● &nbsp;{{ transaction.statusLabel }}</span></td><td><strong :class="transaction.kind">{{ transaction.kind === 'in' ? '+' : '-' }}{{ formatRupiah(transaction.amount) }}</strong></td><td><button type="button" class="transaction-action" :class="{ alert: transaction.action === 'Lacak Paket' }" @click="handleTransactionAction(transaction)">{{ transaction.action === 'Unduh Bukti' ? '▣' : transaction.action === 'Lacak Paket' ? '⌖' : '◎' }} &nbsp;{{ transaction.action }}</button></td></tr><tr v-if="!filteredTransactions.length"><td colspan="5" class="finance-empty">Tidak ada transaksi yang cocok dengan filter.</td></tr></tbody></table></div><footer class="ledger-footer"><span>Menampilkan {{ filteredTransactions.length ? 1 : 0 }}–{{ filteredTransactions.length }} dari 58 transaksi buku kas</span><div><button type="button" disabled aria-label="Halaman sebelumnya">‹</button><button type="button" class="ledger-current-page">1</button><button type="button" @click="notify('Halaman 2 transaksi dimuat.')">2</button><button type="button" @click="notify('Halaman 3 transaksi dimuat.')">3</button><span>...</span><button type="button" @click="notify('Halaman 12 transaksi dimuat.')">12</button><button type="button" aria-label="Halaman berikutnya" @click="notify('Halaman selanjutnya dimuat.')">›</button></div></footer></section>

